"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2092],{54722:e=>{e.exports=JSON.parse('{"functions":[{"name":"OwnsAtFullPool","desc":"True when the player owns `kindId` and its pool is already at the kind\'s\\nmaximum. Crafting is refused in that case, so a redundant craft never costs\\nmaterials.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"kindId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":91,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}},{"name":"Absorb","desc":"Apply the worn armor to one incoming damage amount and drain its pool by what\\nwas absorbed. Returns the damage that survives to reach health.\\n\\n`efficiency` is the player\'s `ArmorEfficiency` perk bonus, read by the caller.\\nIt multiplies the kind\'s base reduction for both armor types, and the result\\nis hard-clamped to `ArmorConfig.MaxReductionCap` so stacking cannot reach\\nimmunity. A hit never absorbs more than the pool has left, so the overflow of\\nthe hit that breaks a ballistic set still reaches health.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"},{"name":"efficiency","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":114,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}},{"name":"Grant","desc":"Award `kindId` at full pool, or refill it if already owned \u2014 recrafting a\\ndamaged set is how it is repaired. Auto-equips when nothing is worn, so a\\nplayer\'s first craft is immediately useful. Returns false (no-op) when the\\nprofile is missing, the kind is unknown, or it is already at full pool.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"kindId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":157,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}},{"name":"Equip","desc":"Wear an owned kind. Returns `(ok, code)` where code is an `ArmorResultCodes`\\nmember. Equipping an Energy kind at zero reserve is allowed \u2014 it is worn and\\nworthless until recharged, which is the intended failure mode.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"kindId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":181,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}},{"name":"Recharge","desc":"Refill an owned Energy kind\'s reserve from the shared MaterialPool Energy.\\nReturns `(ok, energyAdded, code)`. Spends only the points needed to fill\\n(`MaterialPool.SpendUpTo`), like `TrainFuelManager.handleRefuel`.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"kindId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":207,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}},{"name":"Initialize","desc":"Wire profile lifecycle, force-save registration and the join-time snapshot.\\nCall once.","params":[],"returns":[],"function_type":"static","source":{"line":289,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}}],"properties":[],"types":[],"name":"ArmorManager","desc":"Authority for a player\'s crafted armor: which kinds they own, how much pool\\neach has left, which one is worn, and how much damage the worn one absorbs.\\nOwns the `ArmorConfig.STORE_NAME` ProfileStore (one session per player, key =\\nUserId) and is the sole writer of that state.\\n\\nPersisted per player: `Owned` (a map of kind id \u2192 pool remaining, at most one\\nentry per kind in `ArmorConfig.Kinds`) and `Equipped` (a kind id or nil).\\nEverything else \u2014 maximum pool, reduction, type, tier \u2014 is derived from\\n`ArmorConfig`, so retuning a kind applies retroactively.\\n\\n`Absorb` is the mitigation seam `HealthManager` calls at its single damage\\nsink; it both computes the reduction and drains the pool, because the two\\ncannot be split without the pool going stale. Ballistic kinds are destroyed\\nat zero pool; Energy kinds survive at zero and protect nothing until\\n`Recharge` refills them from the shared pool Energy.","realm":["Server"],"source":{"line":22,"path":"src/ServerStorage/SharedModules/ArmorManager.luau"}}')}}]);